scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var hits = new global.EcsIntegration(new global.EcsAst(engine.rootNode)).uncheckedCalls();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-INT-001',
        title: 'Outbound call without error handling',
        recommendation: 'Check the outcome of every call: test response.haveError() and response.getStatusCode() ' +
            'and handle failures (log with context, retry where safe, surface the error). Wrap execute() in ' +
            'try/catch so exceptions do not abort the transaction silently.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
